//! 🧪️ Original Window domain cursors conserve physical custody through every neutral partial frontier.
use super::*;
use store::snapshot_clone_preparation::{RetainedCloneEdit,RetainedCloneEditCursor,RetainedCloneEditStep};
use semio_framework_value::{FromValue,ToValue,RetirementDemand,retirement::{RetireOwned,controlled::ControlledRetirement},retained_clone::{RetainedClone,RetainedCloneRef,RetainedCloneSource}};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
fn parsed<T:FromValue>(source:&str)->T{semio_framework_pack_json::from_json_str(source,semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
fn semantic<T:ToValue>(original:&T)->serde_json::Value{serde_json::to_value(original.to_value()).unwrap()}
fn law<P,M,E,Q>(base:&serde_json::Value,mutation:&serde_json::Value,post:&serde_json::Value,inverse:&serde_json::Value,issuer:&E,quote:Q)
where P:RetainedClone+Clone+FromValue+ToValue,M:RetireOwned+Sync+FromValue+ToValue,E:RetainedCloneEdit<P,M>,Q:for<'a>Fn(&E::Cursor,RetainedCloneRef<'a,P>,RetainedCloneRef<'a,M>,usize)->Result<RetirementDemand,ValueError>{
 let policy:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let n=|key:&str|policy["grant"][key].as_u64().unwrap()as usize;let grant=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copy"),maximum_capacity_bytes:n("capacity"),maximum_release_bytes:n("release"),maximum_depth:n("depth")};let maximum=policy["maximumTurns"].as_u64().unwrap()as usize;let base_text=serde_json::to_string(base).unwrap();let mutation_text=serde_json::to_string(mutation).unwrap();
 for cancelled_at in policy["cancelAt"].as_array().unwrap().iter().map(|turn|Some(turn.as_u64().unwrap()as usize)).chain([None]){
  let((original_base,original_mutation,mut actual_post),heap)=observe(||{let base=parsed::<P>(&base_text);let post=base.clone();(base,parsed::<M>(&mutation_text),post)});let held=heap.requested_bytes-heap.released_bytes;let(mut born,mut released)=(0,0);
  let((mut base_source,receipt),heap)=observe(||RetainedCloneSource::admit_owned(original_base,(),grant).unwrap_or_else(|(error,_,_)|panic!("original base admission {error}")));assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;
  let((mut mutation_source,receipt),heap)=observe(||RetainedCloneSource::admit_owned(original_mutation,(),grant).unwrap_or_else(|(error,_,_)|panic!("original mutation admission {error}")));assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;
  assert!(issuer.preflight(mutation_source.borrow().get(),store::HistoryLane::Document).unwrap().is_admissible());let((mut cursor,receipt),heap)=observe(||issuer.begin(grant).unwrap());assert!(receipt.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;let mut turns=0;let mut output=None;let mut complete=false;
  while cancelled_at!=Some(turns){assert!(turns<maximum);let(demand,heap)=observe(||quote(&cursor,base_source.borrow(),mutation_source.borrow(),grant.maximum_copy_bytes).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(demand.copy_bytes<=grant.maximum_copy_bytes&&demand.capacity_bytes<=grant.maximum_capacity_bytes&&demand.release_bytes<=grant.maximum_release_bytes&&demand.depth<=grant.maximum_depth);let before=semantic(&actual_post);
   for(axis,denied)in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_copy_bytes:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant},RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant},RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant}].into_iter().enumerate(){if(axis==1&&demand.copy_bytes==0)||(axis==2&&demand.capacity_bytes==0)||(axis==3&&demand.release_bytes==0)||(axis==4&&demand.depth==0){continue;}let(result,heap)=observe(||cursor.advance(base_source.borrow(),&mut actual_post,mutation_source.borrow(),denied).unwrap());assert_eq!(result.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(semantic(&actual_post),before);assert_eq!(quote(&cursor,base_source.borrow(),mutation_source.borrow(),grant.maximum_copy_bytes).unwrap(),demand);}
   let(result,heap)=observe(||cursor.advance(base_source.borrow(),&mut actual_post,mutation_source.borrow(),grant).unwrap());assert!(result.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(result.progress().retained_capacity_bytes,result.progress().released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;turns+=1;if matches!(result,RetainedCloneEditStep::Complete(_)){complete=true;assert_eq!(semantic(&actual_post),*post);let rows=cursor.take_inverse().unwrap();assert_eq!(serde_json::Value::Array(rows.iter().map(semantic).collect()),*inverse);output=Some(rows);break;}
  }
  if !complete{cursor.cancel();}cursor.begin_close();for _ in 0..maximum{if cursor.terminal_is_empty(){break;}let(step,heap)=observe(||cursor.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;}assert!(cursor.terminal_is_empty());assert_eq!(observe(||drop(cursor)).1.released_bytes,0);
  for original in [&mut base_source]{for _ in 0..maximum{if original.terminal_is_empty(){break;}let(step,heap)=observe(||original.close_step(grant).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;}assert!(original.terminal_is_empty());}
  for _ in 0..maximum{if mutation_source.terminal_is_empty(){break;}let(step,heap)=observe(||mutation_source.close_step(grant).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;}assert!(mutation_source.terminal_is_empty());let mut remaining=ControlledRetirement::new((actual_post,output)).unwrap_or_else(|(error,_)|panic!("original post/inverse custody {error}"));for _ in 0..maximum{if remaining.terminal_is_empty(){break;}let(step,heap)=observe(||remaining.step(grant).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;}assert!(remaining.terminal_is_empty());assert_eq!(released,held+born);let((),heap)=observe(||drop((base_source,mutation_source,remaining)));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,policy["terminalDropBytes"].as_u64().unwrap()as usize));eprintln!("[DEBUG] original Window domain cursor cancelAt={cancelled_at:?} complete={complete} turns={turns}, held={held} born={born} released={released}; original five-currency refusal, Serde/SQLite semantics, partial custody, terminalDrop0");
 }
}
#[test]
fn window_original_preparation_domain_cursors_preserve_physical_receipts_and_partial_custody(){
 let policy:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let camera=&policy["camera"];law::<retained_pack_load_tests::RetainedLoadCameraConfig,retained_pack_load_tests::RetainedLoadCameraConfigMutation,_,_>(&camera["base"],&serde_json::json!({"kind":"snapshot","config":camera["next"]}),&camera["next"],&serde_json::json!([{"kind":"snapshot","config":camera["base"]}]),&retained_pack_load_tests::CameraRetainedEdit,|cursor,_,_,_|Ok(cursor.normal_demand()));
 use crate::test_app_mutation_fixture::{TestConfig,TestConfigMutation};use crate::test_app_mutation_fixture::config::preparation::SelectionRetainedEdit;
 use protocol::OpBinary;
 for row in policy["selectionBounds"].as_array().unwrap(){let base=row["base"].as_str();let next=row["next"].as_str().unwrap().repeat(row["repeat"].as_u64().unwrap()as usize);let state=TestConfig{selected:Some(next.clone())};let forward=TestConfigMutation::ChangeTestConfigSelection(crate::test_app_mutation_fixture::ChangeTestConfigSelection{selected:Some(next.clone())});let inverse=TestConfigMutation::ChangeTestConfigSelection(crate::test_app_mutation_fixture::ChangeTestConfigSelection{selected:base.map(str::to_owned)});let independent=serde_json::to_vec(&state.to_value()).unwrap().len()+forward.encode_op().unwrap().len()+inverse.encode_op().unwrap().len();let(quoted,heap)=observe(||crate::test_app_mutation_fixture::config::preparation::selection_prepared_bytes(base,Some(&next)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(quoted,independent);assert_eq!(quoted,row["bytes"].as_u64().unwrap()as usize);assert_eq!(quoted<=1024,row["admissible"].as_bool().unwrap());assert_eq!(SelectionRetainedEdit.preflight(&forward,store::HistoryLane::Document).is_ok(),crate::test_app_mutation_fixture::config::preparation::selection_prepared_bytes(None,Some(&next)).unwrap()<=1024);eprintln!("[DEBUG] original Window selection complete Pack/binary bound {quoted} bytes, independent Serde/native OpBinary, admitted={}",row["admissible"]);}
 for row in policy["selection"].as_array().unwrap(){law::<TestConfig,TestConfigMutation,_,_>(&serde_json::json!({"selected":row["base"]}),&serde_json::json!({"operation":"changeTestConfigSelection","payload":{"selected":row["next"]}}),&serde_json::json!({"selected":row["next"]}),&serde_json::json!([{"operation":"changeTestConfigSelection","payload":{"selected":row["base"]}}]),&SelectionRetainedEdit,|cursor,base,mutation,body|cursor.normal_demand(base.get(),mutation.get(),body));}
}
